solution.js:
const amounts = [450, -300, 12000, 1220, -50, 15000];
const formatMoney = (cents) => `$${(cents / 100).toFixed(2)}`;

function spendingOnly(amounts) {
  return amounts.filter((a) => a > 0);
}

function formatAll(amounts) {
  return amounts.map(formatMoney);
}

function firstBig(amounts) {
  return amounts.find((a) => a >= 10000);
}

function hasRefund(amounts) {
  return amounts.some((a) => a < 0);
}

console.log(spendingOnly(amounts), formatAll(amounts));

